solutions.naive:
class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        ans = 0
        parity = 0
        for bit in range(n.bit_length() - 1, -1, -1):
            parity ^= (n >> bit) & 1
            ans = (ans << 1) | parity
        return ans

solutions.better:
class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        if n == 0:
            return 0
        k = n.bit_length() - 1
        return ((1 << (k + 1)) - 1) - self.minimumOneBitOperations(n ^ (1 << k))

solutions.optimal:
class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        ans = 0
        while n:
            ans ^= n
            n >>= 1
        return ans

